def get_max_order_count(orders):
    # 将订单列表转换为字典
    orders_dict = {order['order_id']: order['order_count'] for order in orders}

    # 统计订单号出现次数
    order_counts = {}
    for order_id, count in orders_dict.items():
        if order_id not in order_counts:
            order_counts[order_id] = 1
        else:
            order_counts[order_id] += 1

    # 找到最多出现次数的订单号
    max_count = max(order_counts.values())
    max_order_id = None
    for order_id, count in order_counts.items():
        if count == max_count:
            max_order_id = order_id
            break

    # 返回最多出现次数的订单号
    return max_order_id
